  draft: { h: string; p: string; items: string[] }
  publish: { b: string; s: string }[]
  attrib: { b: string; s: string }[]
  effectsTitle: RichPart[]
  effectsDeck: string
  effects: { title: string; path: string; text: string }[]
  watchTitle: RichPart[]
  watchDeck: RichPart[]
  monitors: { title: string; text: string; to: string }[]
  panelK: string
  panelItems: string[]
  panelFoot: string
  writeTitle: RichPart[]
  writeDeck: RichPart[]
  agentSteps: { title: string; text: string }[]
  writeLinks: { to: string; label: string }[]
  manuscript: { bar: [string, string]; h: string; p: string; factLabel: string; fact: string; items: string[] }
  citeTitle: RichPart[]
  citeDeck: RichPart[]
  citeDims: { title: string; text: string }[]
  sampleK: string
  sampleTitle: RichPart[]
  sampleNote: string
  citeMore: { to: string; label: string }
  channelTitle: RichPart[]
  channelDeck: RichPart[]
  channels: { name: string; note: string }[]
  channelFine: string
  channelMore: { to: string; label: string }
  diagTitle: RichPart[]
  diagDeck: string
  reportBits: { k: string; v: string }[]
  diagLinks: { to: string; label: string; kind: 'go' | 'ghost' }[]
  agencyTitle: string
  agencyText: string
  agencyMore: { to: string; label: string }
  railsTitle: string
  rails: { kicker: string; title: string; text: string; to: string; cta: string }[]
