export type FlagshipTopic = 'home' | 'tools' | 'visibility' | keyof typeof flagshipFeatures

const flagshipByTopic: Record<string, FlagshipPage> = {
  home: flagshipHome,
  tools: flagshipTools,
  visibility: flagshipVisibility,
  ...flagshipFeatures,
}

export function getFlagship(topic: string): FlagshipPage | undefined {
  return flagshipByTopic[topic]
}
